inline OILT::OILT(const OILT &o)
      : PROVIDER(o.PROVIDER),
        KIND(o.KIND),
        LEFT_NAMESPACE(o.LEFT_NAMESPACE),
        RIGHT_NAMESPACE(o.RIGHT_NAMESPACE),
        HEADER(o.HEADER),
        SHA256(o.SHA256),
        BYTES(o.BYTES),
        ROWS(o.ROWS),
        DUPLICATE_LINES(o.DUPLICATE_LINES),
        LINK_COUNT(o.LINK_COUNT),
        CLEAN_COUNT(o.CLEAN_COUNT),
        AMBIGUOUS_COUNT(o.AMBIGUOUS_COUNT),
        LEFT_ID_COUNT(o.LEFT_ID_COUNT),
        RIGHT_ID_COUNT(o.RIGHT_ID_COUNT),
        DATES_DIFFER_COUNT(o.DATES_DIFFER_COUNT),
        UNREADABLE_DATE_COUNT(o.UNREADABLE_DATE_COUNT),
        GENERATED_AT_MS(o.GENERATED_AT_MS) {
  LINKS.reserve(o.LINKS.size());
  for (const auto &LINKS_ : o.LINKS) { LINKS.emplace_back((LINKS_) ? new OILLinkT(*LINKS_) : nullptr); }
  CONFLICTS.reserve(o.CONFLICTS.size());
  for (const auto &CONFLICTS_ : o.CONFLICTS) { CONFLICTS.emplace_back((CONFLICTS_) ? new OILConflictT(*CONFLICTS_) : nullptr); }
}

